#nullable enable // autogenerated

using MVZ2.Vanilla.Unlocks;
using MVZ2Logic;
using MVZ2Logic.Games;
using MVZ2Logic.Saves;
using PVZEngine;

namespace MVZ2.Vanilla.Saves
{
    public static class VanillaSaveExt
    {
        /// <summary>
        /// 梦境世界是否是梦魇状态。
        /// </summary>
        /// <param name="save"></param>
        /// <returns></returns>
        public static bool DreamIsNightmare(this IGlobalSaveData save)
        {
            return save.IsUnlocked(VanillaUnlockID.dreamIsNightmare);
        }
        public static void SetDreamIsNightmare(this IGlobalSaveData save, bool value)
        {
            if (value)
            {
                save.Unlock(VanillaUnlockID.dreamIsNightmare);
            }
            else
            {
                save.Relock(VanillaUnlockID.dreamIsNightmare);
            }
        }
    }
}
